onClick:
{{
  create_project.run(() => {
    // 1. Refresh the table data once the save is successful
    Project.run(); 

    // 2. Clear the form so it's ready for the next entry
    resetWidget("ProjectForm", true); 

    // 3. Provide professional feedback
    showAlert('Project successfully added to portfolio.', 'success');

    // 4. Optional: Close the modal if the form is in one
    closeModal('Modal1'); 

  }, () => {
    // 5. Handle any server-side errors
    showAlert('Error: Could not save project. Please check your connection.', 'error');
  })
}}
